import {TAX_YEAR,FEDERAL_BRACKETS,ONTARIO_BRACKETS,ACCOUNT_LIMITS,bracketBreakdown,deductionSavings,accountContribution,newRRSPRoom,retirementProjection} from './tax-calculations.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const field=(label,key,value,min=0,max=1000000,step=1)=>`<label class="field"><span>${label}</span><input type="number" data-value="${key}" value="${value}" min="${min}" max="${max}" step="${step}" aria-label="${label}"></label>`;
const select=(label,key,value,options)=>`<label class="field"><span>${label}</span><select data-choice="${key}" aria-label="${label}">${options.map(([id,title])=>`<option value="${id}" ${value===id?'selected':''}>${esc(title)}</option>`).join('')}</select></label>`;
const jurisdictionControl=v=>select('Tax scope','jurisdiction',v,[['ON','Ontario + federal'],['federal','Federal only']]);
const pct=n=>(n*100).toFixed(2)+'%';
const scopeNote=j=>j==='ON'?'Ontario resident example; 2026 rules.':'Federal component only, before any Québec abatement. Provincial/territorial tax is NOT included.';
const modelNote='Uses taxable income before the proposed deduction, not gross salary. Assumes adult full-year Canadian residence, no dependants, and net income equals taxable income. Includes basic personal credits; Ontario adds surtax, the basic tax reduction without dependants and the health premium. Excludes CPP/EI credits and deductions, employment credit, LIFT, age/pension/spousal/tuition/medical/charitable credits, refundable credits, benefits, dividend/capital-gain rules, AMT and foreign taxes. This is a bracket-learning estimate, not a tax return, net-pay or refund calculator.';
function breakdown(result,money){return `<div class="table-scroll"><table><thead><tr><th>Tax components</th><th>Before deduction</th><th>After deduction</th></tr></thead><tbody>${[['Taxable income',result.before.taxableIncome,result.after.taxableIncome],['Federal tax after basic personal credit',result.before.federal,result.after.federal],...(result.before.jurisdiction==='ON'?[['Ontario basic tax after personal credit',result.before.ontarioBasic,result.after.ontarioBasic],['Ontario surtax',result.before.surtax,result.after.surtax],['Ontario basic tax reduction',-result.before.ontarioReduction,-result.after.ontarioReduction],['Ontario health premium',result.before.healthPremium,result.after.healthPremium]]:[]),['Illustrative tax',result.before.total,result.after.total]].map(([label,b,a])=>`<tr><th>${label}</th><td>${money(b)}</td><td>${money(a)}</td></tr>`).join('')}</tbody></table></div>`}
function bracketTable(income,jurisdiction,money){const list=[['Federal',FEDERAL_BRACKETS],...(jurisdiction==='ON'?[['Ontario',ONTARIO_BRACKETS]]:[])];return `<details class="year-table"><summary>See how income fills each bracket</summary><div class="table-scroll"><table><thead><tr><th>Component</th><th>Taxable income band</th><th>Rate</th><th>Your portion</th><th>Tax before credits</th></tr></thead><tbody>${list.flatMap(([label,b])=>bracketBreakdown(income,b).map(r=>`<tr><th>${label}</th><td>${money(r.from)}–${r.upTo===Infinity?'above':money(r.upTo)}</td><td>${pct(r.rate)}</td><td>${money(r.portion)}</td><td>${money(r.tax)}</td></tr>`)).join('')}</tbody></table></div></details>`}
export function renderTaxActivity(name,a,money){
 if(!['tax','accounts','retirement'].includes(name))return null;
 money=n=>new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD',minimumFractionDigits:2,maximumFractionDigits:2}).format(n);
 const jurisdiction=a.jurisdiction==='federal'?'federal':'ON';
 if(name==='tax'){
  const income=a.income??80000,deduction=a.deduction??5000,r=deductionSavings(income,deduction,jurisdiction);
  return `<div class="activity"><div class="activity-head"><strong>2026 income-tax bracket lab</strong><span>Ontario example or federal component</span></div><div class="activity-content"><div class="lab-prompt">Change taxable income across a bracket boundary. Only the portion in a higher bracket gets the higher rate. Then add an eligible RRSP/FHSA deduction and compare.</div>${jurisdictionControl(jurisdiction)}${field('Taxable income before this deduction ($)','income',income)}${field('Eligible deduction claimed now ($)','deduction',deduction)}<div class="tax-results"><p class="fineprint"><strong>${scopeNote(jurisdiction)}</strong></p><div class="stats"><div class="stat">Illustrative tax before<strong>${money(r.before.total)}</strong></div><div class="stat good">Illustrative tax after<strong>${money(r.after.total)}</strong></div><div class="stat good">Estimated tax reduction<strong>${money(r.saving)}</strong></div></div><div class="stats"><div class="stat">Average rate before<strong>${pct(r.averageRate)}</strong></div><div class="stat">Tax on next $1 before<strong>${pct(r.marginalRate)}</strong></div><div class="stat">Deduction applied<strong>${money(r.deduction)}</strong></div></div><div class="lab-insight"><strong>A tax reduction is not automatically a refund.</strong><p>Your refund or balance owing also depends on tax already withheld and other return details. A deduction lowers income used in the model; a non-refundable credit lowers tax. If the deduction crosses brackets, one flat marginal rate will not calculate the whole saving.</p></div>${breakdown(r,money)}${bracketTable(income,jurisdiction,money)}${deduction>income?'<div class="banner">This example applies no more deduction than taxable income. Unused eligible deductions require their own carryforward rules.</div>':''}</div><p class="fineprint">${modelNote} Rates and limits reviewed October 24, 2026; annual values do not update automatically.</p></div></div>`;
 }
 if(name==='accounts'){
  const account=['tfsa','rrsp','fhsa'].includes(a.account)?a.account:'rrsp',income=a.income??80000,contribution=a.contribution??5000;
  const room=account==='tfsa'?(a.tfsaRoom??7000):account==='rrsp'?(a.rrspRoom??15000):(a.fhsaRoom??8000);
  const deductionRoom=account==='tfsa'?0:account==='rrsp'?(a.rrspDeductionRoom??15000):(a.fhsaDeductionRoom??8000),lifetimeUsed=a.fhsaLifetimeUsed??0;
  const r=accountContribution({account,income,contribution,room,deductionRoom,lifetimeUsed,jurisdiction});
  const earned=a.earnedIncome??80000,pa=a.pensionAdjustment??0;
  const accountCopy={tfsa:'TFSA contributions are not deductible. Qualifying growth and withdrawals are generally tax-free. Withdrawals generally create room again on January 1 of the next calendar year; investment losses do not create new room.',rrsp:'Eligible RRSP contributions may be deducted now or in a later year. Tax-deferred growth is not the same as tax-free withdrawals: ordinary withdrawals are taxable and usually do not restore room. Employer/group RRSP contributions also use room.',fhsa:'Eligible cash FHSA contributions may be deductible. Qualifying first-home withdrawals are tax-free. RRSP-to-FHSA transfers use FHSA participation room but do not create a new deduction. This exercise models new cash contributions only.'}[account];
  return `<div class="activity"><div class="activity-head"><strong>Account limits & contribution tax effect</strong><span>2026 · fictional starting inputs</span></div><div class="activity-content"><div class="lab-prompt">The annual headline limit is not necessarily your personal room. Use your own records and CRA information, updated for recent transactions. These defaults are a fictional example—not a statement of your eligibility.</div>${select('Account to explore','account',account,[['tfsa','TFSA'],['rrsp','RRSP'],['fhsa','FHSA']])}${jurisdictionControl(jurisdiction)}${field('Taxable income before new deduction ($)','income',income)}${field('Planned new cash contribution ($)','contribution',contribution)}${field('Available contribution / participation room ($)',account==='tfsa'?'tfsaRoom':account==='rrsp'?'rrspRoom':'fhsaRoom',room)}${account!=='tfsa'?field('Available deduction room for this exercise ($)',account==='rrsp'?'rrspDeductionRoom':'fhsaDeductionRoom',deductionRoom):''}${account==='fhsa'?field('FHSA lifetime contributions + RRSP transfers already used ($)','fhsaLifetimeUsed',lifetimeUsed,0,40000):''}<div class="tax-results"><div class="lab-insight"><strong>${account.toUpperCase()}: the tax treatment</strong><p>${accountCopy}</p></div><div class="stats"><div class="stat">Within entered room<strong>${money(r.allowed)}</strong></div><div class="stat">Modelled deduction now<strong>${money(r.deductible)}</strong></div><div class="stat good">Current-year tax reduction<strong>${money(r.saving)}</strong></div></div>${r.excess>0?`<div class="banner">${money(r.excess)} of the planned contribution exceeds the entered room/lifetime allowance. It is excluded from this model. Do not treat an excess contribution as permitted.</div>`:''}${r.unusedDeduction>0&&account!=='tfsa'?`<p class="fineprint">${money(r.unusedDeduction)} of the modelled new contribution is not deducted now because of the entered deduction room or income. Eligibility and carryforward rules must be checked separately.</p>`:''}<div class="table-scroll"><table><thead><tr><th>2026 headline rule</th><th>What it means</th></tr></thead><tbody><tr><th>TFSA: $7,000 new annual dollar limit</th><td>Personal room can be higher through unused eligible room and prior-year withdrawals, or lower after contributions. Residency and age matter; opening an account does not create extra room.</td></tr><tr><th>RRSP: $33,810 maximum new room</th><td>Generally the lesser of 18% of prior-year earned income and the annual dollar limit, adjusted for pensions and other rules. Existing unused room can make the personal limit higher.</td></tr><tr><th>FHSA: $8,000 new annual room; $40,000 lifetime</th><td>Room starts when the first FHSA is opened. Ordinary unused participation room carryforward is capped at $8,000, so a later year's ordinary room can reach $16,000. Contributions and RRSP transfers share room.</td></tr></tbody></table></div><p class="fineprint"><strong>${scopeNote(jurisdiction)}</strong> Saving is tax before minus tax after the modelled deduction. TFSA saving is $0 because there is no contribution deduction; that does not mean the account has no tax advantages.</p></div>${account==='rrsp'?`<details class="year-table"><summary>Explore how ordinary new RRSP room is generated</summary>${field('Previous-year earned income, not all income ($)','earnedIncome',earned)}${field('Previous-year pension adjustment ($)','pensionAdjustment',pa)}<div class="tax-results"><div class="lab-insight"><strong>Illustrative new 2026 room: ${money(newRRSPRoom(earned,pa))}</strong><p>max(0, min(18% × prior-year earned income, $33,810) − pension adjustment). This is not your total room or available contribution room. It excludes prior unused room, unused contributions, PAR/PSPA and other adjustments; use the relevant CRA figures and current records.</p></div></div></details>`:''}<p class="fineprint">Assumes an eligible adult Canadian resident and, for FHSA, that the opening and deduction conditions are met. Room inputs are manually supplied, not calculated from age or residency. This exercise models new cash contributions only; previously contributed but undeducted amounts, special FHSA re-participation room and transfer cases need separate treatment. It does not encourage contributions above room. ${modelNote}</p></div></div>`;
 }
 const input={currentAge:a.currentAge??30,retireAge:a.retireAge??65,retirementYears:a.retirementYears??25,savings:a.savings??10000,monthly:a.monthly??300,annualReturn:a.annualReturn??4,inflation:a.inflation??2,cppMonthly:a.cppMonthly??0,oasMonthly:a.oasMonthly??0,pensionMonthly:a.pensionMonthly??0,goalMonthly:a.goalMonthly??3000};
 const r=retirementProjection(input);
 return `<div class="activity"><div class="activity-head"><strong>Retirement: connect the income sources</strong><span>Today's dollars · before tax</span></div><div class="activity-content"><div class="lab-prompt">Use estimates from your statements, not maximum advertised pensions. The model does not determine CPP/QPP, OAS or workplace-pension eligibility. Start with benefits at $0, then enter estimates only if relevant.</div>${field('Current age','currentAge',input.currentAge,18,79)}${field('Retirement age','retireAge',input.retireAge,18,80)}${field('Years to fund after retirement','retirementYears',input.retirementYears,1,50)}${field('Current savings ($)','savings',input.savings,0,2000000)}${field('Monthly saving in today’s dollars ($)','monthly',input.monthly,0,20000)}${field('Assumed annual return after fees (%)','annualReturn',input.annualReturn,-10,15,.1)}${field('Annual inflation (%)','inflation',input.inflation,0,10,.1)}${field('Estimated monthly CPP / QPP, today’s dollars ($)','cppMonthly',input.cppMonthly,0,10000)}${field('Estimated monthly OAS, today’s dollars ($)','oasMonthly',input.oasMonthly,0,10000)}${field('Estimated monthly workplace pension, today’s dollars ($)','pensionMonthly',input.pensionMonthly,0,20000)}${field('Target monthly income before tax, today’s dollars ($)','goalMonthly',input.goalMonthly,0,20000)}<div class="tax-results">${r.error?`<div class="banner">${esc(r.error)}</div>`:`<div class="stats"><div class="stat">Years to save<strong>${r.years}</strong></div><div class="stat good">Projected savings at retirement<strong>${money(r.savingsAtRetirement)}</strong></div><div class="stat">Assumed real annual return<strong>${pct(r.realAnnual)}</strong></div></div><div class="stats"><div class="stat">Entered pension income / month<strong>${money(r.monthlyPension)}</strong></div><div class="stat">Remaining monthly target<strong>${money(r.monthlyGap)}</strong></div><div class="stat">Model savings needed<strong>${money(r.requiredSavings)}</strong></div></div><div class="lab-insight"><strong>${r.shortfall>0?'Modelled savings gap: '+money(r.shortfall):'Modelled savings above this scenario: '+money(r.surplus)}</strong><p>Try retiring later, changing saving, or using a lower return. This constant-return illustration is not a guarantee of sustainable withdrawals: sequence of returns, longevity, tax, changing spending and benefit timing can change the outcome.</p></div>`}</div><p class="fineprint">All amounts are in today's purchasing power and before tax. Real annual return = (1 + nominal return)/(1 + inflation) − 1; equivalent monthly rate = (1 + real annual return)^(1/12) − 1. Savings contributions arrive at month-end and maintain constant purchasing power (nominal contributions rise with inflation). The retirement amount is the present value of the remaining monthly income target over the selected years, using the same assumed real return before/after retirement and no ending balance. Pension estimates are assumed to maintain purchasing power and start at retirement; actual indexation and start dates may differ. No eligibility, CPP contribution history, OAS residence/recovery tax, GIS or withdrawal taxes are calculated. Do not enter an employer match twice if already included in savings or a pension estimate.</p></div></div>`;
}
